theme.customCSS:
/* index-rezo-la-mer.css est PARTAGÉ : ses teintes océan (bandeaux des searchHeader, dégradés) sont recolorées ici aux couleurs d'Open Atlas — rouge du logo sur l'encre bleu nuit. `:root:root` bat le `:root` de la feuille, `:root:root.dark` son `.dark`. */
:root:root {
  --ocean-deep: oklch(0.22 0.017 264);
  --ocean-mid: oklch(0.32 0.030 264);
  --ocean-light: oklch(0.45 0.120 18);
  --ocean-surface: oklch(0.60 0.209 18);
  --ocean-foam: oklch(0.93 0.035 18);
  --turquoise: var(--primary);
  --turquoise-light: color-mix(in oklab, var(--primary) 70%, white);
  --cyan-bright: var(--primary);
  --shadow-ocean: 0 10px 40px -10px oklch(0.22 0.017 264 / 0.45);
  --shadow-glow: 0 0 30px color-mix(in oklab, var(--primary) 35%, transparent);
  --gradient-section: linear-gradient(135deg, color-mix(in oklab, var(--primary) 8%, var(--background)), color-mix(in oklab, var(--accent) 70%, var(--background)));
  /* Encre rouge des textes, et rouge du logo pour les traits (filet des surtitres, liens du schéma). */
  --oa-ink: var(--primary);
  --oa-ink-hover: color-mix(in oklab, var(--primary) 78%, black);
  --oa-line: oklch(0.5994 0.2087 18.1);
}
:root:root.dark {
  --ocean-deep: oklch(0.1830 0.0172 268.7);
  --ocean-mid: oklch(0.2469 0.0228 262.4);
  --ocean-light: oklch(0.36 0.090 18);
  --shadow-ocean: 0 10px 40px -10px oklch(0 0 0 / 0.7);
  --shadow-glow: 0 0 40px color-mix(in oklab, var(--primary) 40%, transparent);
  --gradient-section: linear-gradient(135deg, var(--ocean-deep), color-mix(in oklab, var(--primary) 16%, var(--ocean-mid)));
  --oa-ink: oklch(0.6802 0.1904 17.8);
  --oa-ink-hover: oklch(0.7640 0.1418 15.1);
}
/* En sombre, le rouge des boutons (#CC2443 : blanc dessus à 5,4:1) ne tient que 3,5:1 en TEXTE sur la nuit.
   Les aplats gardent `primary`, l'encre texte passe au rouge clair de la maquette (#F75B6B, 5,9:1). */
:root.dark .text-primary, :root.dark .hover\:text-primary:hover { color: var(--oa-ink); }

/* ── Accueil « Nuit » (maquette de Simon, oct. 2026) ─────────────────────────────────────────
   Blocs `html` de l'accueil : classes oa-*, tokens du thème uniquement — le mode clair suit seul.
   Largeur utile 72rem, marges latérales calées sur les sections de code (px-4 / sm:px-6 / lg:px-8). */
.oa-band { padding: 6rem 1rem; background: var(--background); color: var(--foreground); }
.oa-band--alt { background: var(--muted); }
.oa-band--head { padding-bottom: 1.75rem; }
@media (min-width: 640px) { .oa-band { padding-inline: 1.5rem; } }
@media (min-width: 1024px) { .oa-band { padding-inline: 2rem; } }
.oa-wrap { max-width: 72rem; margin-inline: auto; }
.oa-stack { display: flex; flex-direction: column; gap: 2.5rem; }
.oa-head { display: flex; flex-direction: column; gap: 0.875rem; max-width: 44rem; }
.oa-eyebrow { display: inline-flex; align-items: center; gap: 0.625rem; font-size: 0.75rem; font-weight: 600; letter-spacing: 0.1em; text-transform: uppercase; color: var(--muted-foreground); }
.oa-eyebrow::before { content: ""; flex: none; width: 1.5rem; height: 2px; background: var(--oa-line); }
.oa-h1 { margin: 0; font-size: clamp(2.5rem, 5.2vw, 4rem); line-height: 1.04; font-weight: 700; letter-spacing: -0.025em; }
.oa-h2 { margin: 0; font-size: clamp(1.875rem, 3.4vw, 2.5rem); line-height: 1.1; font-weight: 700; }
.oa-h3 { margin: 0; font-size: 1.75rem; font-weight: 700; }
.oa-h4 { margin: 0; font-size: 1.1875rem; font-weight: 700; }
.oa-ink { color: var(--oa-ink); }
.oa-lead { margin: 0; max-width: 44ch; font-size: 1.1875rem; line-height: 1.6; color: var(--muted-foreground); }
.oa-text { margin: 0; font-size: 1.0625rem; line-height: 1.65; color: var(--muted-foreground); }
.oa-text-sm { margin: 0; font-size: 1rem; line-height: 1.6; color: var(--muted-foreground); }
.oa-actions { display: flex; flex-wrap: wrap; gap: 0.875rem; }
.oa-btn { display: inline-flex; align-items: center; min-height: 3.125rem; padding: 0 1.625rem; border-radius: 999px; font-size: 0.9375rem; font-weight: 600; text-decoration: none; transition: background-color 0.15s, border-color 0.15s; }
.oa-btn--sm { min-height: 2.75rem; padding: 0 1.25rem; font-size: 0.875rem; }
.oa-btn--primary { background: var(--primary); color: var(--primary-foreground); }
.oa-btn--primary:hover { background: color-mix(in oklab, var(--primary) 86%, white); }
.oa-btn--ghost { border: 1px solid color-mix(in oklab, var(--foreground) 30%, transparent); color: var(--foreground); }
.oa-btn--ghost:hover { border-color: var(--foreground); }
.oa-btn:focus-visible, .oa-more:focus-visible, .oa-net a:focus-visible { outline: 2px solid var(--ring); outline-offset: 3px; }
#outils, #reseau, #accompagnement, #rejoindre { scroll-margin-top: 5.5rem; }

.oa-hero { padding-block: 6.5rem 6rem; }
.oa-hero__grid { display: grid; gap: 3rem; align-items: center; }
.oa-hero__text { display: flex; flex-direction: column; gap: 1.5rem; }
.oa-hero__text .oa-actions { margin-top: 0.375rem; }
.oa-hero__art { display: flex; justify-content: center; }
.oa-hero__art img { width: min(380px, 64vw); height: auto; }
.oa-only-dark { display: none; }
:root.dark .oa-only-dark { display: block; }
:root.dark .oa-only-light { display: none; }

.oa-grid { display: grid; gap: 1.375rem; margin: 0; padding: 0; list-style: none; }
.oa-card { display: flex; flex-direction: column; gap: 1rem; padding: 2.25rem; border-radius: 1.25rem; background: var(--card); color: var(--card-foreground); border: 1px solid var(--border); }
.oa-kicker { font-size: 0.75rem; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; color: var(--oa-ink); }
.oa-chips { display: flex; flex-wrap: wrap; gap: 0.5rem; margin: 0.25rem 0 0; padding: 0; list-style: none; }
.oa-chips li { padding: 0.4375rem 0.75rem; border-radius: 999px; border: 1px solid color-mix(in oklab, var(--foreground) 18%, transparent); font-size: 0.8125rem; color: color-mix(in oklab, var(--foreground) 55%, var(--muted-foreground)); }
.oa-chips li.is-more { border-style: dashed; color: var(--muted-foreground); }
.oa-more { margin-top: auto; padding-top: 0.5rem; font-size: 0.9375rem; font-weight: 600; color: var(--oa-ink); text-decoration: none; }
.oa-more:hover, .oa-net a:hover { color: var(--oa-ink-hover); }

.oa-head-row { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: flex-end; gap: 1.5rem; }
#projets-apercu { box-sizing: content-box; max-width: 72rem; padding: 1.75rem 1rem 6rem; }
@media (min-width: 640px) { #projets-apercu { padding-inline: 1.5rem; } }
@media (min-width: 1024px) { #projets-apercu { padding-inline: 2rem; } }

.oa-principles li { display: flex; flex-direction: column; gap: 0.75rem; }
.oa-principles p { margin: 0; font-size: 0.9375rem; line-height: 1.6; color: var(--muted-foreground); }
.oa-num { font-size: 0.875rem; font-weight: 700; color: var(--oa-ink); }

.oa-split { display: grid; gap: 3rem; align-items: center; }
.oa-split--top { align-items: start; }

/* Schéma « au cœur » : boîte au ratio de la maquette (520×420), tout positionné en % pour suivre l'écran. */
.oa-net { position: relative; width: 100%; max-width: 520px; aspect-ratio: 520 / 420; margin-inline: auto; }
.oa-net svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.oa-net .is-hot { stroke: var(--oa-line); stroke-width: 2.5; }
.oa-net .is-cold { stroke: color-mix(in oklab, var(--foreground) 28%, transparent); stroke-width: 1.5; stroke-dasharray: 5 6; }
.oa-net circle.is-hot { stroke-width: 3; }
.oa-net circle.is-cold { stroke: var(--foreground); stroke-width: 2; stroke-dasharray: none; }
.oa-net__hub { position: absolute; left: 38.46%; top: 35.71%; width: 23.08%; aspect-ratio: 1; display: grid; place-items: center; border-radius: 50%; background: var(--card); border: 1px solid color-mix(in oklab, var(--foreground) 15%, transparent); }
.oa-net__hub img { width: 70%; height: auto; }
.oa-net__label { position: absolute; left: 50%; top: 67.14%; transform: translateX(-50%); font-size: 0.8125rem; font-weight: 600; white-space: nowrap; }
.oa-net a { position: absolute; padding: 0.4375rem 0.75rem; border-radius: 999px; background: var(--card); border: 1px solid color-mix(in oklab, var(--foreground) 15%, transparent); font-size: 0.8125rem; color: var(--foreground); text-decoration: none; white-space: nowrap; }
.oa-net .oa-net__p1 { left: 3.85%; top: 4.76%; }
.oa-net .oa-net__p2 { right: 0; top: 7.14%; }
.oa-net .oa-net__p3 { left: 0; bottom: 4.76%; }
.oa-net .oa-net__p4 { right: 0; bottom: 6.19%; }
@media (max-width: 480px) { .oa-net a, .oa-net__label { padding: 0.3125rem 0.625rem; font-size: 0.75rem; } }

.oa-box { margin-top: 0.875rem; padding: 1.5rem; display: flex; flex-direction: column; gap: 0.75rem; border-radius: 1rem; background: var(--card); border: 1px solid var(--border); }
.oa-box p { margin: 0; font-size: 0.9375rem; line-height: 1.6; color: var(--muted-foreground); }
.oa-steps { margin: 0; padding: 0; list-style: none; }
.oa-steps li { display: flex; gap: 1.125rem; padding: 1.25rem 0; border-bottom: 1px solid color-mix(in oklab, var(--foreground) 12%, transparent); font-size: 1rem; line-height: 1.5; }
.oa-steps li:last-child { border-bottom: 0; }
.oa-steps .oa-num { flex: none; font-size: 1rem; }

.oa-join { padding-block: 6.5rem; }
.oa-join .oa-wrap { max-width: 53.75rem; display: flex; flex-direction: column; align-items: center; gap: 1.125rem; text-align: center; }
.oa-join .oa-h2 { font-size: clamp(2rem, 3.8vw, 2.75rem); }
.oa-join .oa-text { max-width: 56ch; }
.oa-join .oa-actions { justify-content: center; margin-top: 0.5rem; }

@media (min-width: 560px) { .oa-grid--4 { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 960px) {
  .oa-hero__grid, .oa-grid--2, .oa-split { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .oa-grid--4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}
